// Happy Place - Clean ES6 p5.js Conversion
let dim = 900;
let num = 128;
let time = 0;
let friends = [];
let maxpal = 512;
let goodcolor = ["#2b2d42", "#8d99ae", "#edf2f4", "#ef233c", "#d90429", "#ffb703", "#023047", "#219ebc", "#8ecae6"];

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(255);
  frameRate(30);
  resetAll();
}

function draw() {
  let bass = (typeof sub_bass !== 'undefined') ? sub_bass : 0;
  let perc = (typeof percussive !== 'undefined') ? percussive : 0;

  for (let c = 0; c < num; c++) {
    if (friends[c]) friends[c].move();
  }
  for (let c = 0; c < num; c++) {
    if (friends[c]) {
      friends[c].expose();
      friends[c].exposeConnections();
    }
  }
  if (time % 2 === 0) {
    for (let c = 0; c < num; c++) {
      if (friends[c]) friends[c].findHappyPlace(bass);
    }
  }
  time++;
}

function mousePressed() {
  resetAll();
  background(255);
}

function resetAll() {
  friends = new Array(num);
  let cx = width / 2;
  let cy = height / 2;
  let rad = min(width, height) * 0.35;
  for (let x = 0; x < num; x++) {
    let fx = cx + rad * cos(TWO_PI * x / num);
    let fy = cy + rad * sin(TWO_PI * x / num);
    friends[x] = new Friend(fx, fy, x);
  }

  for (let k = 0; k < num * 2.2; k++) {
    let a = int(floor(random(num)));
    let b = int(floor(a + random(22)) % num);
    if (b >= num || b < 0) b = 0;
    if (a !== b && friends[a] && friends[b]) {
      friends[a].connectTo(b);
      friends[b].connectTo(a);
    }
  }
}

class Friend {
  constructor(X, Y, Id) {
    this.x = X;
    this.y = Y;
    this.dx = X;
    this.dy = Y;
    this.vx = 0;
    this.vy = 0;
    this.id = Id;
    this.numcon = 0;
    this.maxcon = 10;
    this.lencon = 10 + int(random(50));
    this.connections = new Array(this.maxcon);
    this.numsands = 3;
    this.sands = [];
    this.myc = somecolor();
    for (let n = 0; n < this.numsands; n++) {
      this.sands.push(new SandPainter());
    }
  }

  expose() {
    for (let d = -2; d < 3; d++) {
      let a = 0.5 - abs(d) / 5.0;
      stroke(0, 256 * a);
      point(this.x + d, this.y);
      stroke(255, 256 * a);
      point(this.x + d - 1, this.y - 1);
    }
    for (let d = -2; d < 3; d++) {
      let a = 0.5 - abs(d) / 5.0;
      stroke(0, 256 * a);
      point(this.x, this.y + d);
      stroke(255, 256 * a);
      point(this.x - 1, this.y + d - 1);
    }
  }

  exposeConnections() {
    for (let n = 0; n < this.numcon; n++) {
      let targetIdx = this.connections[n];
      if (friends[targetIdx]) {
        let ox = friends[targetIdx].x;
        let oy = friends[targetIdx].y;
        for (let s = 0; s < this.numsands; s++) {
          this.sands[s].render(this.x, this.y, ox, oy);
        }
      }
    }
  }

  move() {
    this.x += this.vx;
    this.y += this.vy;
    this.vx *= 0.92;
    this.vy *= 0.92;
  }

  connectTo(f) {
    if (this.numcon < this.maxcon) {
      if (!this.friendOf(f)) {
        this.connections[this.numcon] = f;
        this.numcon++;
      }
    }
  }

  friendOf(x) {
    for (let n = 0; n < this.numcon; n++) {
      if (this.connections[n] === x) return true;
    }
    return false;
  }

  findHappyPlace(bassBoost = 0) {
    let ax = 0.0;
    let ay = 0.0;
    for (let n = 0; n < num; n++) {
      if (friends[n] && friends[n] !== this) {
        let ddx = friends[n].x - this.x;
        let ddy = friends[n].y - this.y;
        let d = sqrt(ddx * ddx + ddy * ddy);
        let t = atan2(ddy, ddx);
        let isFriend = this.friendOf(n);
        let effectiveLen = this.lencon * (1.0 + bassBoost * 0.5);

        if (isFriend) {
          if (d > effectiveLen) {
            ax += 4.0 * cos(t);
            ay += 4.0 * sin(t);
          }
        } else {
          if (d < effectiveLen) {
            ax += (effectiveLen - d) * cos(t + PI);
            ay += (effectiveLen - d) * sin(t + PI);
          }
        }
      }
    }
    this.vx += ax / 42.22;
    this.vy += ay / 42.22;
  }
}

class SandPainter {
  constructor() {
    this.p = random(1.0);
    this.c = somecolor();
    this.g = random(0.01, 0.1);
  }

  render(x, y, ox, oy) {
    let colObj = color(this.c);
    let r = red(colObj), g_col = green(colObj), b_col = blue(colObj);
    stroke(r, g_col, b_col, 28);
    point(ox + (x - ox) * sin(this.p), oy + (y - oy) * sin(this.p));

    this.g += random(-0.05, 0.05);
    let maxg = 0.22;
    if (this.g < -maxg) this.g = -maxg;
    if (this.g > maxg) this.g = maxg;

    let w = this.g / 10.0;
    for (let i = 0; i < 11; i++) {
      let a = 0.1 - i / 110;
      stroke(r, g_col, b_col, 256 * a);
      point(ox + (x - ox) * sin(this.p + sin(i * w)), oy + (y - oy) * sin(this.p + sin(i * w)));
      point(ox + (x - ox) * sin(this.p - sin(i * w)), oy + (y - oy) * sin(this.p - sin(i * w)));
    }
  }
}

function somecolor() {
  return goodcolor[int(random(goodcolor.length))];
}
